selected.compute:
options = read('/input/options')
result = []
for size in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, size):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
    else:
        result = []
if len(result) > 0:
    if not exists('/output/selection'):
        write('/output/selection', result)
    if receipt('report') == 'success':
        pass
    elif receipt('report') == 'unknown':
        status('report')
    elif receipt('report') == 'unattempted' and status('report') == 'not_sent':
        send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
